// EmployeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import api from "../api/axios";   // your custom axios instance

const EmployeeDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user);

  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchTickets = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await api.get('tickets/');
        console.log('Full API response:', response.data);
        console.log('Current user ID:', user?.id);

        // Filter by creator (safe for string/number mismatch)
        const myTickets = response.data.filter(
          ticket => ticket.creator?.id?.toString() === user?.id?.toString()
        );

        setTickets(myTickets);
      } catch (err) {
        setError('Failed to load tickets. Check console for details.');
        console.error("Could not load your tickets:", err?.response?.data || err.message);
      } finally {
        setLoading(false);
      }
    };

    if (user && token) fetchTickets();
  }, [token, user]);

  // Case-insensitive status counts (matches title case from spec)
  const countOpen = tickets.filter(t => t.status?.toUpperCase() === 'OPEN').length;
  const countInProgress = tickets.filter(t => t.status?.toUpperCase() === 'IN PROGRESS').length;
  const countResolved = tickets.filter(t => t.status?.toUpperCase() === 'RESOLVED').length;

  // Priority and Status colors - use title case
  const getPriorityColor = (priority) => {
    const upper = priority?.toUpperCase() || '';
    switch (upper) {
      case 'HIGH': case 'VERY HIGH': return '#ff4d4f';
      case 'MEDIUM': case 'NORMAL': return '#faad14';
      case 'LOW': return '#52c41a';
      default: return '#d9d9d9';
    }
  };

  const getStatusColor = (status) => {
    const upper = status?.toUpperCase() || '';
    switch (upper) {
      case 'OPEN': return '#1890ff';
      case 'IN PROGRESS': return '#faad14';
      case 'RESOLVED': return '#52c41a';
      default: return '#d9d9d9';
    }
  };

  if (loading) return <div style={styles.loading}>Loading your tickets...</div>;
  if (error) return <div style={styles.error}>{error}</div>;

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>My Tickets Dashboard</h2>

      {/* Dashboard Counts */}
      <div style={styles.countsGrid}>
        <div style={{ ...styles.countCard, background: '#e6f7ff', borderColor: '#1890ff' }}>
          <h3 style={styles.countNumber}>{countOpen}</h3>
          <p style={styles.countLabel}>Open Tickets</p>
        </div>
        <div style={{ ...styles.countCard, background: '#fffbe6', borderColor: '#faad14' }}>
          <h3 style={styles.countNumber}>{countInProgress}</h3>
          <p style={styles.countLabel}>In Progress</p>
        </div>
        <div style={{ ...styles.countCard, background: '#f6ffed', borderColor: '#52c41a' }}>
          <h3 style={styles.countNumber}>{countResolved}</h3>
          <p style={styles.countLabel}>Resolved</p>
        </div>
      </div>

      {/* Tickets List */}
      {tickets.length === 0 ? (
        <p style={styles.noTickets}>You haven't created any tickets yet.</p>
      ) : (
        <div style={styles.ticketsContainer}>
          {tickets.map(ticket => (
            <div key={ticket.id} style={styles.ticketCard}>
              <div style={styles.ticketHeader}>
                <h4 style={styles.ticketTitle}>#{ticket.id} - {ticket.title}</h4>
                <span style={{ ...styles.badge, background: getPriorityColor(ticket.priority), color: '#fff' }}>
                  Priority: {ticket.priority}
                </span>
                <span style={{ ...styles.badge, background: getStatusColor(ticket.status), color: '#fff' }}>
                  Status: {ticket.status}
                </span>
              </div>
              <p style={styles.ticketDescription}>{ticket.description}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};


// Inline styles for clean, attractive UI (no external libs needed)
const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: 'Arial, sans-serif',
    background: '#f0f2f5',
    borderRadius: '8px',
  },
  title: {
    fontSize: '24px',
    marginBottom: '24px',
    color: '#333',
  },
  countsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '16px',
    marginBottom: '32px',
  },
  countCard: {
    padding: '16px',
    border: '1px solid',
    borderRadius: '8px',
    textAlign: 'center',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
  },
  countNumber: {
    fontSize: '32px',
    margin: '0',
    color: '#333',
  },
  countLabel: {
    fontSize: '16px',
    color: '#666',
    margin: '8px 0 0',
  },
  ticketsContainer: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  },
  ticketCard: {
    padding: '16px',
    border: '1px solid #d9d9d9',
    borderRadius: '8px',
    background: '#fff',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
  },
  ticketHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    marginBottom: '8px',
  },
  ticketTitle: {
    margin: '0',
    fontSize: '18px',
    flex: 1,
  },
  badge: {
    padding: '4px 12px',
    borderRadius: '16px',
    fontSize: '12px',
    fontWeight: 'bold',
  },
  ticketDescription: {
    fontSize: '14px',
    color: '#666',
    margin: '0',
  },
  loading: {
    textAlign: 'center',
    fontSize: '18px',
    color: '#1890ff',
  },
  error: {
    textAlign: 'center',
    fontSize: '18px',
    color: '#ff4d4f',
  },
  noTickets: {
    textAlign: 'center',
    fontSize: '16px',
    color: '#666',
  },
};

export default EmployeeDashboard;
